#include <stdio.h>
#include <string.h>

/* teste do desafio aponta-para-mim — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   O endereco muda a cada execucao: por isso o teste NUNCA compara com um
   numero fixo — ele compara as linhas impressas entre si (a captura do
   stdout acontece dentro do proprio cenario, modelo cenario-do-harness). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void apontaParaMim(void);

SM_TEST(o_papel_tem_o_endereco_da_casa) {
    freopen("sm_saida_1.tmp", "w", stdout);
    apontaParaMim();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char papel[80] = "(nada impresso)";
    char casa[80] = "(nada impresso)";
    fgets(papel, 80, f);
    fgets(casa, 80, f);
    checa_int("a primeira linha mostrou um endereco", !(strcmp(papel, "(nada impresso)") == 0), 1,
              "a primeira linha e o ponteiro p impresso com %p");
    checa_str("p e &x sao o mesmo endereco", papel, casa,
              "p guarda o endereco de x: imprimir p da a mesma linha que imprimir &x");
    fclose(f);
}

SM_TEST(o_endereco_do_papel_e_outro) {
    freopen("sm_saida_2.tmp", "w", stdout);
    apontaParaMim();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char papel[80] = "(nada impresso)";
    char casa[80] = "(nada impresso)";
    char onde[80] = "(nada impresso)";
    fgets(papel, 80, f);
    fgets(casa, 80, f);
    fgets(onde, 80, f);
    checa_int("a terceira linha mostrou um endereco", !(strcmp(onde, "(nada impresso)") == 0), 1,
              "a terceira linha e &p, o endereco do proprio ponteiro");
    checa_int("o endereco do papel nao e o da casa", !(strcmp(onde, papel) == 0), 1,
              "o papel mora em outro lugar: &p e diferente do endereco que p guarda");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na terceira linha: nenhuma linha extra e aceita");
    fclose(f);
}

